# Review package: f8a3f379bd35304d4fbc99e7553c3b711379df11..eb28bc3

## Commits
eb28bc3 Add greet function with custom formatting
a35c9f8 Add greeting implementation plan

## Files changed
 greet.js      |  6 ++++++
 greet.test.js | 28 ++++++++++++++++++++++++++++
 package.json  |  5 ++++-
 plan.md       | 24 ++++++++++++++++++++++++
 4 files changed, 62 insertions(+), 1 deletion(-)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..dd6c28b
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,6 @@
+function greet(name) {
+  const displayName = name && name.trim() !== '' ? name : 'friend';
+  return `Hello there, ${displayName}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..c3e339c
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,28 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for valid name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello there, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello there, friend!');
+});
+
+test('greet handles undefined input gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello there, friend!');
+});
+
+test('greet handles null input gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello there, friend!');
+});
+
+test('greet handles names with spaces', () => {
+  const result = greet('John Doe');
+  assert.strictEqual(result, 'Hello there, John Doe!');
+});
